     .brand { display: flex; align-items: center; gap: 10px; font-weight: 900; letter-spacing: -.04em; }
     .brand-mark { display: grid; width: 34px; height: 34px; place-items: center; border: 2px solid var(--ink); border-radius: 50%; background: var(--green); color: #202823; font-size: 13px; }
     .topnav { display: flex; align-items: center; gap: 22px; font-size: 12px; font-weight: 800; }
     .topnav a { text-decoration-thickness: 2px; text-underline-offset: 4px; }
     .toggle { border: 2px solid var(--ink); border-radius: 999px; background: var(--paper-2); color: var(--ink); padding: 8px 12px; font: inherit; font-size: 12px; font-weight: 800; cursor: pointer; box-shadow: 2px 2px 0 var(--ink); }
     .toggle:active { transform: translate(2px, 2px); box-shadow: none; }
     .hero { position: relative; overflow: hidden; padding: 76px 0 66px; border-bottom: 1px solid var(--line); }
     .hero::after { position: absolute; content: "14"; right: 2%; top: 22px; color: var(--hero-mark); font-size: clamp(150px, 31vw, 350px); font-weight: 1000; line-height: 1; letter-spacing: -.13em; pointer-events: none; z-index: -1; }
     .eyebrow { display: inline-flex; gap: 9px; align-items: center; color: var(--green-dark); background: var(--green); border: 1px solid var(--ink); padding: 5px 10px; font-size: 11px; font-weight: 900; letter-spacing: .09em; text-transform: uppercase; }
     body.night .eyebrow { color: #1a2416; }
     .eyebrow .dot { width: 7px; height: 7px; background: currentColor; border-radius: 50%; }
     h1, h2, h3, p { margin-top: 0; }
     h1 { max-width: 780px; margin: 22px 0 18px; font-family: ui-sans-serif, system-ui, sans-serif; font-weight: 950; font-size: clamp(48px, 7vw, 78px); letter-spacing: normal; line-height: 1.16; }
     .hero-line { display: block; white-space: nowrap; }
     .hero-line > span { color: var(--orange); }
     .hero-copy { max-width: 590px; margin-bottom: 28px; color: var(--muted); font-family: ui-sans-serif, system-ui, sans-serif; font-size: clamp(16px, 2.2vw, 19px); }
     .hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; }
     .cta { display: inline-block; border: 2px solid var(--ink); padding: 11px 16px; background: var(--ink); color: var(--paper); font-weight: 900; text-decoration: none; box-shadow: var(--shadow); transition: transform .15s ease; }
     .cta:hover { transform: translate(2px, 2px); box-shadow: 3px 3px 0 var(--ink); }
     .hero-note { color: var(--muted); font-size: 11px; }
     .ticker { overflow: hidden; border-bottom: 2px solid var(--ink); background: var(--green); color: #202823; white-space: nowrap; }
     .ticker-inner { padding: 9px 0; font-size: 11px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; }
     .ticker span { padding: 0 13px; }
     .ticker b { color: #547b2a; }
     section { padding: 68px 0; }
     .section-head { display: flex; align-items: end; justify-content: space-between; gap: 22px; margin-bottom: 26px; }
     .kicker { margin-bottom: 8px; color: var(--muted); font-size: 11px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; }
     h2 { margin-bottom: 0; font-family: ui-sans-serif, system-ui, sans-serif; font-size: clamp(32px, 5vw, 54px); font-weight: 950; line-height: 1.16; letter-spacing: normal; }
     .section-note { max-width: 280px; margin: 0; color: var(--muted); font-size: 11px; }
     .crew-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 20px; }
     .card { grid-column: span 2; overflow: hidden; border: 2px solid var(--ink); background: var(--paper-2); box-shadow: var(--shadow); }
     .card:nth-child(4) { grid-column: 2 / span 2; }
     .card:nth-child(5) { grid-column: 4 / span 2; }
     .portrait { position: relative; display: block; width: 100%; aspect-ratio: 1.35; object-fit: cover; background: var(--blue); border-bottom: 2px solid var(--ink); filter: saturate(.88); }
     .card:nth-child(2) .portrait { background: var(--lavender); }
     .card:nth-child(3) .portrait { background: var(--green); }
     .card:nth-child(4) .portrait { background: var(--orange); }
     .card:nth-child(5) .portrait { background: var(--blue); }
     .card-inner { padding: 17px; }
     .card-meta { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 6px; color: var(--muted); font-size: 9px; font-weight: 900; letter-spacing: .09em; text-transform: uppercase; }
     .card h3 { margin-bottom: 12px; font-family: ui-sans-serif, system-ui, sans-serif; font-size: 25px; line-height: 1; letter-spacing: -.06em; }
     .detail { margin: 0 0 13px; font-size: 11px; line-height: 1.6; }
     .detail strong { color: var(--orange); }
     .fact { margin: 0; border-top: 1px dashed var(--line); padding-top: 12px; color: var(--muted); font-size: 10px; }
     .fact b { color: var(--ink); }
     .ai-section { position: relative; background: var(--ink); color: var(--paper); }
     .ai-section .kicker, .ai-section .section-note { color: color-mix(in srgb, var(--paper), transparent 32%); }
     .ai-section .section-head { align-items: end; }
     .ai-section h2 { max-width: 730px; }
     .ai-board { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 34px; }
     .ai-panel { padding: 23px; border: 1px solid color-mix(in srgb, var(--paper), transparent 60%); background: color-mix(in srgb, var(--paper), transparent 94%); }
     .ai-panel.agree { border-top: 5px solid var(--green); }
     .ai-panel.differ { border-top: 5px solid var(--orange); }
     .ai-panel h3 { margin-bottom: 16px; font-size: 13px; letter-spacing: .05em; text-transform: uppercase; }
     .ai-panel ul { display: grid; gap: 14px; margin: 0; padding: 0; list-style: none; }
     .ai-panel li { position: relative; padding-left: 23px; font-family: ui-sans-serif, system-ui, sans-serif; font-size: 14px; }
     .ai-panel li::before { position: absolute; left: 0; top: 0; color: var(--green); content: "↳"; font-family: monospace; font-weight: 900; }
     .differ li::before { color: var(--orange); }
     .quote-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; margin-top: 16px; }
     .quote { min-height: 122px; padding: 17px; background: var(--green); color: #202823; font-size: 11px; font-weight: 800; }
     .quote:nth-child(2) { background: var(--blue); }
     .quote:nth-child(3) { background: var(--lavender); }
     .quote cite { display: block; margin-top: 12px; font-size: 9px; font-style: normal; text-transform: uppercase; letter-spacing: .08em; }
     .future { padding: 62px 0; }
     .future-box { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 24px; padding: 26px; border: 2px solid var(--ink); background: var(--orange); color: #251d19; box-shadow: var(--shadow); }
     .future-box h2 { max-width: 600px; font-size: clamp(26px, 4vw, 41px); }
     .future-box p { max-width: 620px; margin: 12px 0 0; font-family: ui-sans-serif, system-ui, sans-serif; font-size: 14px; }
     .big-arrow { display: grid; width: 72px; height: 72px; place-items: center; border: 2px solid #251d19; border-radius: 50%; font-size: 34px; transform: rotate(-35deg); }
     footer { border-top: 1px solid var(--line); padding: 24px 0 36px; color: var(--muted); font-size: 10px; }
     .footer-row { display: flex; justify-content: space-between; align-items: center; gap: 15px; }
     .footer-row strong { color: var(--ink); }
     @media (max-width: 760px) {
       .wrap { width: min(100% - 32px, 600px); }
       .topbar { padding: 15px 0; }
       .topnav { gap: 12px; }
       .topnav a { display: none; }
       .hero { padding: 57px 0 47px; }
-      .hero::after { top: 38px; right: -6%; }
+      .hero::after { top: 0; right: 0; font-size: clamp(64px, 18vw, 90px); }
       section { padding: 52px 0; }
       .section-head { display: block; }
       .section-note { margin-top: 13px; }
       .crew-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
       .card { grid-column: auto !important; }
       .card:last-child { grid-column: 1 / -1 !important; width: calc(50% - 7px); justify-self: center; }
       .card-inner { padding: 13px; }
       .card h3 { font-size: 22px; }
       .ai-board { grid-template-columns: 1fr; }
       .quote-strip { grid-template-columns: 1fr; }
       .quote { min-height: auto; }
       .future-box { grid-template-columns: 1fr; padding: 21px; }
       .big-arrow { width: 52px; height: 52px; font-size: 25px; }
     }
     @media (max-width: 420px) {
       .wrap { width: calc(100% - 26px); }
       .brand { font-size: 12px; }
       .brand-mark { width: 30px; height: 30px; }
       .toggle { padding: 7px 9px; font-size: 10px; }
